import {
  type Conversation,
  type ConversationEvent,
  ConversationEventType,
  type RawEvent,
  type UnionEventType,
  type Utterance,
  UtteranceType,
} from "../types";
import { toReplayEvent } from "./broker-event";
import { isConversationEvent, isInternalRasaMessage, isUtterance } from "./conversation";

const INTERNAL_RASA_SLOTS = ["flow_hashes", "dialogue_stack"];

function isInternalRasaSlot(slotName: string): boolean {
  return INTERNAL_RASA_SLOTS.includes(slotName);
}

function generateFlowStartedAssertion(event: ConversationEvent): string {
  return `- flow_started: "${event.flowId}"`;
}

function generateFlowCompletedAssertion(event: ConversationEvent): string {
  return `- flow_completed:\n      flow_id: "${event.flowId}"`;
}

function generateFlowCancelledAssertion(event: ConversationEvent): string {
  return `- flow_cancelled:\n      flow_id: "${event.flowId}"`;
}

function generateSlotWasSetAssertion(event: ConversationEvent): string {
  if (isInternalRasaSlot(event.name ?? "")) {
    return "";
  }
  return `- slot_was_set:\n    - name: "${event.name}"\n      value: ${JSON.stringify(event.slotValue)}`;
}

function generateActionExecutedAssertion(event: ConversationEvent): string {
  return `- action_executed: "${event.actionText}"`;
}

function generateSkillActivatedAssertion(event: ConversationEvent): string {
  return `- skill_activated:\n      skill_id: "${event.skillId}"`;
}

function generateSkillCompletedAssertion(event: ConversationEvent): string {
  return `- skill_completed:\n      skill_id: "${event.skillId}"`;
}

function generateSkillStepAssertion(key: string, event: ConversationEvent): string {
  const lines = [`- ${key}:`, `      skill_id: "${event.skillId}"`];
  if (event.stepId) lines.push(`      step_id: "${event.stepId}"`);
  return lines.join("\n");
}

function generateOrderedBlockEnteredAssertion(event: ConversationEvent): string {
  return [
    `- ordered_block_entered:`,
    `      skill_id: "${event.skillId}"`,
    `      block_id: "${event.blockId}"`,
  ].join("\n");
}

function generateOrderedBlockStepAssertion(key: string, event: ConversationEvent): string {
  const lines = [
    `- ${key}:`,
    `      skill_id: "${event.skillId}"`,
    `      block_id: "${event.blockId}"`,
  ];
  if (event.stepId) lines.push(`      step_id: "${event.stepId}"`);
  return lines.join("\n");
}

function generateMemoryWasSetAssertion(event: ConversationEvent): string {
  const lines = [`- memory_was_set:`, `    - name: "${event.name}"`];
  if (event.value !== undefined && event.value !== null) {
    lines.push(`      value: ${JSON.stringify(event.value)}`);
  }
  return lines.join("\n");
}

function generateMemoryWasClearedAssertion(event: ConversationEvent): string {
  return `- memory_was_cleared:\n    - name: "${event.name}"`;
}

function generateToolExecutedAssertion(event: ConversationEvent): string {
  const source = event.metadata?.tool_source;
  if (!source || (source === "mcp" && !event.metadata?.tool_mcp_server)) {
    return "";
  }
  const lines = [
    `- tool_executed:`,
    `      tool_name: "${event.metadata?.tool_name ?? event.name}"`,
    `      source: "${source}"`,
  ];
  if (source === "mcp" && event.metadata?.tool_mcp_server) {
    lines.push(`      mcp_server: "${event.metadata.tool_mcp_server}"`);
  }
  const skillId = event.metadata?.skill_id;
  if (skillId) lines.push(`      skill_id: "${skillId}"`);
  if (event.metadata?.tool_is_error === true || event.metadata?.tool_is_error === false) {
    lines.push(`      is_error: ${event.metadata.tool_is_error}`);
  }
  const args = event.metadata?.tool_arguments;
  if (args && typeof args === "object" && Object.keys(args).length) {
    lines.push(`      arguments: ${JSON.stringify(args)}`);
  }
  return lines.join("\n");
}

function generateBotUtteredAssertion(utterance: Utterance): string {
  const utterName = utterance.metadata?.utter_action;
  const lines: string[] = [
    `- bot_uttered:`,
    utterName ? `    utter_name: "${utterName}"` : `    text_matches: "${utterance.text}"`,
  ];

  if (utterance.responseData?.quickReplies.length) {
    lines.push(`    buttons:`);
    for (const button of utterance.responseData.quickReplies) {
      lines.push(`      - title: "${button.title}"`);
      lines.push(`        payload: "${button.payload}"`);
    }
  }

  return lines.join("\n");
}

function eventToAssertion(event: Utterance | ConversationEvent): string {
  if (isConversationEvent(event)) {
    switch (event.conversationEventType) {
      case ConversationEventType.FlowStarted:
        return generateFlowStartedAssertion(event);
      case ConversationEventType.FlowCompleted:
        return generateFlowCompletedAssertion(event);
      case ConversationEventType.FlowCancelled:
        return generateFlowCancelledAssertion(event);
      case ConversationEventType.Slot:
        return generateSlotWasSetAssertion(event);
      case ConversationEventType.Action:
        return generateActionExecutedAssertion(event);
      case ConversationEventType.SkillActivated:
        return generateSkillActivatedAssertion(event);
      case ConversationEventType.SkillCompleted:
        return generateSkillCompletedAssertion(event);
      case ConversationEventType.SkillCancelled:
        return generateSkillStepAssertion("skill_cancelled", event);
      case ConversationEventType.SkillInterrupted:
        return generateSkillStepAssertion("skill_interrupted", event);
      case ConversationEventType.SkillResumed:
        return generateSkillStepAssertion("skill_resumed", event);
      case ConversationEventType.OrderedBlockEntered:
        return generateOrderedBlockEnteredAssertion(event);
      case ConversationEventType.OrderedBlockCompleted:
        return generateOrderedBlockStepAssertion("ordered_block_completed", event);
      case ConversationEventType.OrderedBlockCancelled:
        return generateOrderedBlockStepAssertion("ordered_block_cancelled", event);
      case ConversationEventType.OrderedBlockInterrupted:
        return generateOrderedBlockStepAssertion("ordered_block_interrupted", event);
      case ConversationEventType.OrderedBlockResumed:
        return generateOrderedBlockStepAssertion("ordered_block_resumed", event);
      case ConversationEventType.MemorySet:
        return generateMemoryWasSetAssertion(event);
      case ConversationEventType.MemoryCleared:
        return generateMemoryWasClearedAssertion(event);
      case ConversationEventType.ToolExecuted:
        return generateToolExecutedAssertion(event);
      default:
        return "";
    }
  } else if (isUtterance(event) && event.type === UtteranceType.Bot) {
    return generateBotUtteredAssertion(event);
  }
  return "";
}

type Step = {
  user: string;
  assertions: string[];
};

export function generateTestCase(
  sessionId: string,
  conversation: Conversation,
  mantle = false,
): string {
  const steps: Step[] = [];
  let currentStep: Step | null = null;
  let hasStarted = false;

  for (const event of conversation.events) {
    if (isUtterance(event) && event.type === UtteranceType.User) {
      hasStarted = true;

      if (currentStep) {
        steps.push(currentStep);
      }

      currentStep = {
        user: event.text,
        assertions: [],
      };
    } else if (hasStarted) {
      if (!currentStep) {
        currentStep = {
          user: "N/A",
          assertions: [],
        };
      }
      // Mantle rejects action_executed; flow and slot twins are stripped upstream.
      if (
        mantle &&
        isConversationEvent(event) &&
        event.conversationEventType === ConversationEventType.Action
      ) {
        continue;
      }
      const assertion = eventToAssertion(event);
      if (assertion) {
        currentStep.assertions.push(assertion);
      }
    }
  }

  if (currentStep) {
    steps.push(currentStep);
  }

  const lines: string[] = [];
  lines.push(`test_cases:`);
  lines.push(`  - test_case: ${sessionId}`);
  lines.push(`    steps:`);
  for (const step of steps) {
    lines.push(`      - user: ${JSON.stringify(step.user)}`);
    if (step.assertions.length > 0) {
      lines.push(`        assertions:`);
      for (const assertion of step.assertions) {
        for (const line of assertion.split("\n")) {
          lines.push(`          ${line}`);
        }
      }
    }
  }

  return lines.join("\n");
}

function triggerDownload(content: string, filename: string, mimeType: string) {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
  URL.revokeObjectURL(url);
}

function extractRawEvents(conversations: Conversation[]): ReturnType<typeof toReplayEvent>[] {
  return conversations.flatMap((conversation) =>
    conversation.events
      .map((event: UnionEventType) => event.metadata?.rawEvent)
      .filter((raw): raw is RawEvent => raw != null)
      .map((raw) => toReplayEvent(raw)),
  );
}

export function downloadRawTrackerLogs(conversations: Conversation[], sessionId: string) {
  const rawEvents = extractRawEvents(conversations);
  const json = JSON.stringify(rawEvents, null, 2);
  triggerDownload(json, `tracker-logs-${sessionId}.json`, "application/json");
}

export function downloadE2eTests(conversations: Conversation[], sessionId: string, mantle = false) {
  const lastConversation = conversations[conversations.length - 1];
  if (!lastConversation) return;

  const yaml = generateTestCase(sessionId, lastConversation, mantle);
  triggerDownload(yaml, `e2e-test-${sessionId}.yml`, "text/yaml");
}

export function formatConversationForCopy(conversation: Conversation): string {
  const lines: string[] = [];

  for (const event of conversation.events) {
    if (!isUtterance(event)) continue;
    if (event.type === UtteranceType.User) {
      if (isInternalRasaMessage(event.text)) continue;
      lines.push(`User: ${event.text}`);
    } else {
      lines.push(`Agent: ${event.text}`);
    }
  }

  return lines.join("\n");
}

export async function copyConversation(conversations: Conversation[]): Promise<void> {
  const conversation = conversations.at(-1);
  if (!conversation) return;
  await navigator.clipboard.writeText(formatConversationForCopy(conversation));
}
